package com.lims.model;
import java.sql.Timestamp; import java.util.ArrayList; import java.util.List;
public class ExportReceipt { private int receiptId,requestId; private String customerName,warehouseName,status,note,cancelReason,managerName; private Timestamp receiptDate,approvedDate; private List<ExportReceiptItem> items=new ArrayList<>(); public int getReceiptId(){return receiptId;} public void setReceiptId(int v){receiptId=v;} public int getRequestId(){return requestId;} public void setRequestId(int v){requestId=v;} public String getCustomerName(){return customerName;} public void setCustomerName(String v){customerName=v;} public String getWarehouseName(){return warehouseName;} public void setWarehouseName(String v){warehouseName=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getNote(){return note;} public void setNote(String v){note=v;} public String getCancelReason(){return cancelReason;} public void setCancelReason(String v){cancelReason=v;} public String getManagerName(){return managerName;} public void setManagerName(String v){managerName=v;} public Timestamp getReceiptDate(){return receiptDate;} public void setReceiptDate(Timestamp v){receiptDate=v;} public Timestamp getApprovedDate(){return approvedDate;} public void setApprovedDate(Timestamp v){approvedDate=v;} public List<ExportReceiptItem> getItems(){return items;} public void setItems(List<ExportReceiptItem> v){items=v;} }
